# Let me analyze the pattern more carefully
# I'll look at which cells have main characters and their positions

main_chars = {(1, 6, 7): True, (1, 21, 7): True, (3, 3, 6): True, (3, 18, 6): True, 
              (4, 0, 9): True, (4, 7, 0): True, (4, 10, 9): True, (4, 17, 0): True, 
              (7, 21, 7): True, (15, 13, 1): True, (15, 23, 1): True, 
              (16, 0, 9): True, (19, 7, 0): True}

# Cell structure: 2 rows x 4 cols
# Cell at cell_row (0-7), cell_col (0-4)
# cell_row 0-1, cell_row 3-4, cell_row 6-7, etc.
# cell_col 0-3, cell_col 5-8, etc.

def get_cell_from_main_char(r, c):
    """Map global coord to cell grid coords"""
    # Find which cell row
    cell_rows = [0, 3, 6, 9, 12, 15, 18, 21]
    cell_row = next((i for i, tr in enumerate(cell_rows) if tr <= r < tr+2), None)
    if cell_row is None:
        return (cell_row, None)

    # Find which cell col
    cell_cols = [0, 5, 10, 15, 20]
    cell_col = next((i for i, tc in enumerate(cell_cols) if tc <= c < tc+4), None)
    if cell_col is None:
        return (None, cell_col)

    return (cell_row, cell_col)

cell_contents = {}
for (r, c, val) in main_chars:
    cr, cc = get_cell_from_main_char(r, c)
    key = (cr, cc)
    if key in cell_contents:
        if val not in cell_contents[key]:
            cell_contents[key].append(val)
    else:
        cell_contents[key] = [val]

print("Cell contents:")
for key in sorted(cell_contents.keys()):
    print(f"  Cell ({key[0]},{key[1]}): {cell_contents[key]}")

